    // data while a fresh fetch happens in the background, across every view
    // that depends on the `"products"` tag. The action returns immediately so
    // the admin can continue working.
    await syncCatalog()
    revalidateTag('products', 'max')
  }

  return (
    <main style={{ maxWidth: 900, margin: '0 auto', padding: 24 }}>
      <header
        style={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'flex-start',
          gap: 16,
          marginBottom: 24,
        }}
      >
        <div>
          <h1 style={{ margin: 0 }}>Product Catalog</h1>
          <p style={{ margin: '8px 0 0', color: '#666' }}>
            {products.length} products · cached for fast browsing
          </p>
        </div>

        {/* Regular HTML form invoking the inline Server Action. Progressive
